+SupportersWidget::SupportersWidget(QWidget *parent) :
+    QWidget(parent),
+    isDevelopmentBuild_(true),
+    scrollArea_(nullptr),
+    contentWidget_(nullptr)
+{
+    // Try to load supporters data first, then determine if we're in dev mode
+    loadSupportersData();
+
+    // If the supporters data is empty or has no sponsors/donors, treat as development build
+    if (!supportersData_.isEmpty()) {
+        QJsonObject sponsors = supportersData_["sponsors"].toObject();
+        QJsonArray donors = supportersData_["donors"].toArray();
+
+        // Check if we have any actual sponsor or donor data
+        bool hasSponsors = !sponsors["platinum"].toArray().isEmpty() ||
+                          !sponsors["gold"].toArray().isEmpty() ||
+                          !sponsors["silver"].toArray().isEmpty() ||
+                          !sponsors["bronze"].toArray().isEmpty();
+        bool hasDonors = !donors.isEmpty();
+
+        isDevelopmentBuild_ = !(hasSponsors || hasDonors);
+    }
+
+    setupUi();
+}
+
+SupportersWidget::~SupportersWidget()
+{
+}
+
+void SupportersWidget::setupUi()
+{
+    QVBoxLayout *mainLayout = new QVBoxLayout(this);
+    mainLayout->setContentsMargins(0, 0, 0, 0);
+
+    scrollArea_ = new QScrollArea(this);
+    scrollArea_->setWidgetResizable(true);
+    scrollArea_->setFrameShape(QFrame::NoFrame);
+    scrollArea_->setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);
+
+    contentWidget_ = new QWidget();
+    QVBoxLayout *contentLayout = new QVBoxLayout(contentWidget_);
+    contentLayout->setSpacing(12);
+    contentLayout->setContentsMargins(16, 16, 16, 16);
+
+    if (isDevelopmentBuild_) {
+        setupDevelopmentView();
+    } else {
+        setupReleaseView();
+    }
+
+    scrollArea_->setWidget(contentWidget_);
+    mainLayout->addWidget(scrollArea_);
+}
+
+void SupportersWidget::loadSupportersData()
+{
+    QFile file(":/about/supporters.json");
+    if (!file.open(QIODevice::ReadOnly)) {
+        // File not available - this shouldn't happen in release builds
+        return;
+    }
+
+    QByteArray data = file.readAll();
+    QJsonDocument doc = QJsonDocument::fromJson(data);
+    if (doc.isObject()) {
+        supportersData_ = doc.object();
+    }
+}
+
+void SupportersWidget::setupDevelopmentView()
+{
+    QVBoxLayout *layout = qobject_cast<QVBoxLayout*>(contentWidget_->layout());
+    if (!layout) return;
+
+    // Use warning background color from ColorUtils for the info box
+    QColor warningBg = ColorUtils::warningBackground();
+    QColor warningBorder = warningBg.darker(110);
+
+    QFrame *infoFrame = new QFrame();
+    infoFrame->setFrameShape(QFrame::StyledPanel);
+    infoFrame->setStyleSheet(
+        QString("QFrame { background-color: %1; border: 1px solid %2; border-radius: 6px; }")
+            .arg(warningBg.name()).arg(warningBorder.name())
+    );
+
+    QVBoxLayout *infoLayout = new QVBoxLayout(infoFrame);
+    infoLayout->setContentsMargins(16, 16, 16, 16);
+    infoLayout->setSpacing(12);
+
+    // Use contrasting text color
+    QColor textColor = ColorUtils::contrastingTextColor(warningBg);
+
+    QLabel *titleLabel = new QLabel(tr("<b>Development Build</b>"));
+    titleLabel->setStyleSheet(QString("QLabel { color: %1; background: transparent; border: none; }")
+                              .arg(textColor.name()));
+
+    QLabel *descLabel = new QLabel(
+        tr("This is a development version. Sponsor information is only included in official releases.")
+    );
+    descLabel->setWordWrap(true);
+    descLabel->setStyleSheet(QString("QLabel { color: %1; background: transparent; border: none; }")
+                             .arg(textColor.name()));
+
+    QLabel *linksLabel = new QLabel();
+    linksLabel->setText(
+        QString("%1<a href=\"https://www.wireshark.org/sponsor/\">%2</a> %3 "
+                "<a href=\"https://www.wireshark.org/donate/\">%4</a>")
+            .arg(ColorUtils::themeLinkStyle())
+            .arg(tr("Become a sponsor"))
+            .arg(tr("or"))
+            .arg(tr("support the project"))
+    );
+    linksLabel->setOpenExternalLinks(true);
+    linksLabel->setStyleSheet(QString("QLabel { color: %1; background: transparent; border: none; }")
+                              .arg(textColor.name()));
+
+    infoLayout->addWidget(titleLabel);
+    infoLayout->addWidget(descLabel);
+    infoLayout->addWidget(linksLabel);
+
+    layout->addWidget(infoFrame);
+
+    // Donors section placeholder
+    QLabel *donorsHeader = new QLabel(tr("<h3>Donors</h3>"));
+    layout->addWidget(donorsHeader);
+
+    QLabel *donorsPlaceholder = new QLabel(
+        tr("<i>Donor list not available in development builds.</i>")
+    );
+    layout->addWidget(donorsPlaceholder);
+
+    layout->addStretch();
+}
+
+void SupportersWidget::setupReleaseView()
+{
+    QVBoxLayout *layout = qobject_cast<QVBoxLayout*>(contentWidget_->layout());
+    if (!layout) return;
+
+    createSponsorsSection(layout);
+    createDonorsSection(layout);
+
+    layout->addStretch();
+}
+
+void SupportersWidget::createSponsorsSection(QVBoxLayout *layout)
+{
+    QJsonObject sponsors = supportersData_["sponsors"].toObject();
+
+    // Platinum sponsors - large logo cards
+    QJsonArray platinumSponsors = sponsors["platinum"].toArray();
+    if (!platinumSponsors.isEmpty()) {
+        QWidget *platinumSection = createLogoTierSection(platinumSponsors, SponsorTier::Platinum);
+        layout->addWidget(platinumSection);
+    }
+
+    // Gold sponsors - medium logo cards
+    QJsonArray goldSponsors = sponsors["gold"].toArray();
+    if (!goldSponsors.isEmpty()) {
+        QWidget *goldSection = createLogoTierSection(goldSponsors, SponsorTier::Gold);
+        layout->addWidget(goldSection);
+    }
+
+    // Silver sponsors - simple text links
+    QJsonArray silverSponsors = sponsors["silver"].toArray();
+    if (!silverSponsors.isEmpty()) {
+        QWidget *silverSection = createTextTierSection(silverSponsors, SponsorTier::Silver);
+        layout->addWidget(silverSection);
+    }
+
+    // Bronze sponsors - simple text links
+    QJsonArray bronzeSponsors = sponsors["bronze"].toArray();
+    if (!bronzeSponsors.isEmpty()) {
+        QWidget *bronzeSection = createTextTierSection(bronzeSponsors, SponsorTier::Bronze);
+        layout->addWidget(bronzeSection);
+    }
+}
+
+QWidget* SupportersWidget::createLogoTierSection(const QJsonArray &sponsors, SponsorTier tier)
+{
+    QWidget *section = new QWidget();
+    QHBoxLayout *hLayout = new QHBoxLayout(section);
+    hLayout->setContentsMargins(0, 4, 0, 4);
+    hLayout->setSpacing(16);
+
+    for (const QJsonValue &sponsorVal : sponsors) {
+        QJsonObject sponsor = sponsorVal.toObject();
+        QWidget *card = createSponsorCard(sponsor, tier);
+        hLayout->addWidget(card);
+    }
+
+    hLayout->addStretch();
+    return section;
+}
+
+QWidget* SupportersWidget::createTextTierSection(const QJsonArray &sponsors, SponsorTier tier)
+{
+    QWidget *section = new QWidget();
+    QHBoxLayout *hLayout = new QHBoxLayout(section);
+    hLayout->setContentsMargins(0, 2, 0, 2);
+    hLayout->setSpacing(4);
+
+    // Tier colors - these are intentionally fixed colors for branding
+    QString tierColor;
+    switch (tier) {
+        case SponsorTier::Silver:
+            tierColor = ColorUtils::themeIsDark() ? "#A0A0A0" : "#707070";
+            break;
+        case SponsorTier::Bronze:
+            tierColor = ColorUtils::themeIsDark() ? "#CD853F" : "#8B5A2B";
+            break;
+        default:
+            tierColor = ColorUtils::themeIsDark() ? "#A0A0A0" : "#666666";
+            break;
+    }
+
+    QLabel *tierLabel = new QLabel(QString("<b>%1:</b>").arg(tierToString(tier)));
+    tierLabel->setStyleSheet(QString("QLabel { color: %1; }").arg(tierColor));
+    hLayout->addWidget(tierLabel);
+
+    // Build comma-separated list of linked sponsors
+    QStringList sponsorLinks;
+    for (const QJsonValue &sponsorVal : sponsors) {
+        QJsonObject sponsor = sponsorVal.toObject();
+        QString name = sponsor["name"].toString();
+        QString url = sponsor["url"].toString();
+
+        if (!url.isEmpty()) {
+            sponsorLinks << QString("<a href=\"%1\" style=\"color: %2;\">%3</a>")
+                            .arg(url).arg(tierColor).arg(name);
+        } else {
+            sponsorLinks << name;
+        }
+    }
+
+    QLabel *sponsorsLabel = new QLabel(sponsorLinks.join(", "));
+    sponsorsLabel->setOpenExternalLinks(true);
+    sponsorsLabel->setWordWrap(true);
+    hLayout->addWidget(sponsorsLabel, 1);
+
+    return section;
+}
+
+QWidget* SupportersWidget::createSponsorTierSection(const QString & /* tierName */,
+                                                     const QJsonArray &sponsors,
+                                                     SponsorTier tier)
+{
+    // This method is now deprecated in favor of createLogoTierSection and createTextTierSection
+    return createLogoTierSection(sponsors, tier);
+}
+
+QWidget* SupportersWidget::createSponsorCard(const QJsonObject &sponsor, SponsorTier tier)
+{
+    QFrame *card = new QFrame();
+    card->setFrameShape(QFrame::StyledPanel);
+
+    // Use palette colors for theme compatibility
+    QPalette palette = QApplication::palette();
+    QColor cardBg = palette.color(QPalette::Base);
+    QColor borderColor = palette.color(QPalette::Mid);
+
+    card->setStyleSheet(
+        QString("QFrame { background-color: %1; border: 1px solid %2; border-radius: 6px; }")
+            .arg(cardBg.name()).arg(borderColor.name())
+    );
+
+    QVBoxLayout *cardLayout = new QVBoxLayout(card);
+    cardLayout->setContentsMargins(12, 8, 12, 8);
+    cardLayout->setSpacing(4);
+
+    QString name = sponsor["name"].toString();
+    QString url = sponsor["url"].toString();
+    QString logo = sponsor["logo"].toString();
+
+    // Tier label with branded colors
+    QString tierTextColor;
+    switch (tier) {
+        case SponsorTier::Platinum:
+            tierTextColor = ColorUtils::themeIsDark() ? "#B0B0B0" : "#666666";
+            break;
+        case SponsorTier::Gold:
+            tierTextColor = "#DAA520"; // Goldenrod - works in both themes
+            break;
+        default:
+            tierTextColor = ColorUtils::themeIsDark() ? "#B0B0B0" : "#666666";
+            break;
+    }
+
+    QLabel *tierLabel = new QLabel(tierToString(tier).toUpper());
+    tierLabel->setAlignment(Qt::AlignCenter);
+    tierLabel->setStyleSheet(
+        QString("QLabel { color: %1; font-size: 9px; font-weight: bold; "
+                "background: transparent; border: none; }")
+            .arg(tierTextColor)
+    );
+    cardLayout->addWidget(tierLabel);
+
+    // Logo
+    if (!logo.isEmpty()) {
+        QLabel *logoLabel = new QLabel();
+        logoLabel->setAlignment(Qt::AlignCenter);
+
+        QString logoPath = QString(":/about/sponsors/%1").arg(logo);
+        QPixmap pixmap(logoPath);
+        if (!pixmap.isNull()) {
+            int maxWidth = (tier == SponsorTier::Platinum) ? 160 : 120;
+            int maxHeight = (tier == SponsorTier::Platinum) ? 50 : 40;
+            pixmap = pixmap.scaled(maxWidth, maxHeight, Qt::KeepAspectRatio, Qt::SmoothTransformation);
+            logoLabel->setPixmap(pixmap);
+        } else {
+            logoLabel->setText(QString("<b>%1</b>").arg(name));
+            logoLabel->setStyleSheet("QLabel { background: transparent; border: none; }");
+        }
+
+        if (!url.isEmpty()) {
+            logoLabel->setCursor(Qt::PointingHandCursor);
+            logoLabel->setProperty("url", url);
+            logoLabel->installEventFilter(this);
+        }
+
+        cardLayout->addWidget(logoLabel);
+    } else {
+        // Text-only for sponsors without logos
+        QLabel *nameLabel = new QLabel(QString("<b>%1</b>").arg(name));
+        nameLabel->setAlignment(Qt::AlignCenter);
+        nameLabel->setStyleSheet("QLabel { background: transparent; border: none; }");
+        if (!url.isEmpty()) {
+            nameLabel->setCursor(Qt::PointingHandCursor);
+            nameLabel->setProperty("url", url);
+            nameLabel->installEventFilter(this);
+        }
+        cardLayout->addWidget(nameLabel);
+    }
+
+    return card;
+}
+
+void SupportersWidget::createDonorsSection(QVBoxLayout *layout)
+{
+    QJsonArray donors = supportersData_["donors"].toArray();
+    if (donors.isEmpty()) return;
+
+    // Donors header
+    QLabel *donorsHeader = new QLabel(tr("<h3>Donors</h3>"));
+    layout->addWidget(donorsHeader);
+
+    // Create flowing text of donor names
+    QStringList donorNames;
+    for (const QJsonValue &donor : donors) {
+        if (donor.isString()) {
+            donorNames << donor.toString();
+        } else if (donor.isObject()) {
+            donorNames << donor.toObject()["name"].toString();
+        }
+    }
+
+    // Use palette colors for theme compatibility
+    QPalette palette = QApplication::palette();
+    QColor frameBg = palette.color(QPalette::AlternateBase);
+    QColor borderColor = palette.color(QPalette::Mid);
+    QColor textColor = palette.color(QPalette::Text);
+
+    // Display donors as a flowing paragraph in a styled frame
+    QFrame *donorsFrame = new QFrame();
+    donorsFrame->setFrameShape(QFrame::StyledPanel);
+    donorsFrame->setStyleSheet(
+        QString("QFrame { background-color: %1; border: 1px solid %2; border-radius: 6px; }")
+            .arg(frameBg.name()).arg(borderColor.name())
+    );
+
+    QVBoxLayout *donorsLayout = new QVBoxLayout(donorsFrame);
+    donorsLayout->setContentsMargins(12, 10, 12, 10);
+    donorsLayout->setSpacing(4);
+
+    QLabel *donorsList = new QLabel(donorNames.join(" \u2022 ")); // Bullet separator
+    donorsList->setWordWrap(true);
+    donorsList->setStyleSheet(
+        QString("QLabel { color: %1; background: transparent; border: none; }")
+            .arg(textColor.name())
+    );
+    donorsLayout->addWidget(donorsList);
+
+    // If there are many donors, add a "and X more" indicator
+    int displayedCount = static_cast<int>(donorNames.size());
+    int totalCount = supportersData_["donor_count"].toInt(displayedCount);
+    if (totalCount > displayedCount) {
+        QColor mutedColor = ColorUtils::themeIsDark() ?
+            palette.color(QPalette::Text).darker(130) :
+            palette.color(QPalette::Text).lighter(150);
+        QLabel *moreLabel = new QLabel(tr("+ %1 more").arg(totalCount - displayedCount));
+        moreLabel->setStyleSheet(
+            QString("QLabel { color: %1; font-style: italic; background: transparent; border: none; }")
+                .arg(mutedColor.name())
+        );
+        donorsLayout->addWidget(moreLabel);
+    }
+
+    layout->addWidget(donorsFrame);
+}
+
+QString SupportersWidget::tierToString(SponsorTier tier) const
+{
+    switch (tier) {
+        case SponsorTier::Platinum: return tr("Platinum");
+        case SponsorTier::Gold: return tr("Gold");
+        case SponsorTier::Silver: return tr("Silver");
+        case SponsorTier::Bronze: return tr("Bronze");
+    }
+    return QString();
+}
+
+QString SupportersWidget::tierStyleClass(SponsorTier tier) const
+{
+    switch (tier) {
+        case SponsorTier::Platinum: return "tier-platinum";
+        case SponsorTier::Gold: return "tier-gold";
+        case SponsorTier::Silver: return "tier-silver";
+        case SponsorTier::Bronze: return "tier-bronze";
+    }
+    return QString();
+}
+
+bool SupportersWidget::eventFilter(QObject *obj, QEvent *event)
+{
+    if (event->type() == QEvent::MouseButtonRelease) {
+        QMouseEvent *mouseEvent = static_cast<QMouseEvent*>(event);
+        if (mouseEvent->button() == Qt::LeftButton) {
+            QString url = obj->property("url").toString();
+            if (!url.isEmpty()) {
+                QDesktopServices::openUrl(QUrl(url));
+                return true;
+            }
+        }
+    }
+    return QWidget::eventFilter(obj, event);
+}

